import { MeshBasicNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, Color } = ctx.THREE;

  // Root container
  const root = new Group();

  // Plane geometry and material
  const geometry = new PlaneGeometry(1, 1);
  const material = new MeshBasicNodeMaterial();
  material.color = new Color(0xffffff);
  material.transparent = true;

  const plane = new Mesh(geometry, material);
  // Local transforms (adapter applies scenePosition)
  plane.position.set(0, 0, 0);
  plane.rotation.set(0, 0, 0);
  plane.scale.set(1, 1, 1);
  root.add(plane);

  // Load texture
  let texture = null;
  ctx.textureLoader
    .loadTexture(config.imageUrl)
    .then((tex) => {
      texture = tex;
      material.map = tex;
      material.needsUpdate = true;
    })
    .catch(() => {
      // ignore load errors
    });

  // Text content
  const items = config.textContent ??
    config.intent?.visualSpec?.textContent ??
    [];
  for (const item of items) {
    const fontSize = item.typography?.fontSize ?? 39;
    const textObj = ctx.fontAtlas.createText(item.text ?? '', {
      fontSize,
      color: config.visualSpec?.colors?.paper ?? '#e8ecf2',
      align: 'center',
    });
    textObj.position.set(0, 0, 0.01);
    root.add(textObj);
  }

  // Apply cinematic primitives (if any)
  if (Array.isArray(config.cinematicPrimitives)) {
    for (const prim of config.cinematicPrimitives) {
      if (ctx.primitives[prim.name]) {
        const result = ctx.primitives[prim.name](root, prim.params);
        // store for cleanup
        if (!root.userData._primitiveResults) root.userData._primitiveResults = [];
        root.userData._primitiveResults.push(result);
      }
    }
  }

  // User data and cleanup
  root.userData = {
    handlers: {},
    cleanup() {
      // Dispose primitives
      if (root.userData._primitiveResults) {
        for (const r of root.userData._primitiveResults) {
          if (r && typeof r.cleanup === 'function') r.cleanup();
        }
        root.userData._primitiveResults = null;
      }
      // Dispose material and geometry
      if (material) material.dispose();
      if (geometry) geometry.dispose();
      // Dispose texture
      if (texture) texture.dispose();
      // Kill GSAP timelines
      gsap.globalTimeline.clear();
      // Remove children
      root.traverse((obj) => {
        if (obj !== root && obj.parent) {
          obj.parent.remove(obj);
        }
      });
    },
  };

  return root;
}
